using Microsoft.EntityFrameworkCore;

/// <summary>
/// Cosmos DB context migrated to EF Core 9.
/// Breaking changes addressed:
/// 1. Discriminator property renamed from "Discriminator" to "$type" — explicitly set old name for existing documents.
/// 2. id property no longer contains discriminator — use HasRootDiscriminatorInJsonId(true) for existing documents.
/// 3. Sync I/O no longer supported — all queries/saves must use async equivalents.
/// </summary>
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: Preserve "Discriminator" property name for existing documents
        // (EF Core 9 defaults to "$type")
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix 2: Preserve old compound id format ("EntityType|KeyValue") for existing documents
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

/// <summary>
/// Fix 3: Sync I/O → async. All Cosmos DB queries must use async equivalents.
/// </summary>
class CosmosService
{
    private readonly CosmosDbContext _db;
    public CosmosService(CosmosDbContext db) => _db = db;

    // BEFORE (throws in EF Core 9):
    //   var sessions = _db.Sessions.ToList();
    //   _db.SaveChanges();
    //
    // AFTER:
    public async Task<List<Session>> GetSessionsAsync()
    {
        return await _db.Sessions.ToListAsync();
    }

    public async Task SaveAsync()
    {
        await _db.SaveChangesAsync();
    }
}

